public final class ShortCode {
    private static final String ALPHABET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private static final int BASE = 62;

    // KGS hands out seq; encoding is pure local CPU, no coordination.
    public static String encode(long seq) {
        if (seq == 0) return "a";
        StringBuilder sb = new StringBuilder();
        while (seq > 0) {
            sb.append(ALPHABET.charAt((int) (seq % BASE)));
            seq /= BASE;
        }
        return sb.reverse().toString();
    }

    public static long decode(String code) {
        long n = 0;
        for (int i = 0; i < code.length(); i++) {
            n = n * BASE + ALPHABET.indexOf(code.charAt(i));
        }
        return n;
    }
}

def redirect(short_code, cache, db, queue):
    # 1. Cache first: trade stale-delete risk for speed.
    #    Mitigate with short TTL + explicit invalidate on revoke.
    target = cache.get(short_code)
    if target is None:
        row = db.get_mapping(short_code)  # single-shard point read
        if row is None or row.revoked or row.is_expired():
            return (404, None)
        target = row.long_url
        cache.set(short_code, target, ttl=3600)
    # 2. Never block redirect on analytics.
    queue.emit_async({"code": short_code, "ts": now()})
    return (302, target)
